import random
random.seed(155)
ops, size = [], 0
for _ in range(300):
    r = random.random()
    if size == 0 or r < 0.45:
        ops.append(('push', random.randint(-50, 50)))
        size += 1
    elif r < 0.7:
        ops.append(('pop',))
        size -= 1
    else:
        ops.append(random.choice([('top',), ('min',)]))
